module bug_fixing_optimizer #(\n    parameter MAX_BUGS = 2,\n    parameter MAX_TIME = 8,\n    parameter STATE_SIZE = (MAX_TIME+2) ** MAX_BUGS,\n    parameter DATA_WIDTH = 64,\n    parameter FRACTION_WIDTH = 32\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] B,\n    input wire [3:0] T,\n    input wire [DATA_WIDTH-1:0] f,\n    input wire [DATA_WIDTH-1:0] p [0:MAX_BUGS-1],\n    input wire [DATA_WIDTH-1:0] s [0:MAX_BUGS-1],\n    output reg [DATA_WIDTH-1:0] expected_value,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] S_IDLE = 4'd0;\n    localparam [3:0] S_PRECOMP = 4'd1;\n    localparam [3:0] S_INIT = 4'd2;\n    localparam [3:0] S_LOOP_T = 4'd3;\n    localparam [3:0] S_LOOP_STATE = 4'd4;\n    localparam [3:0] S_LOOP_BUG = 4'd5;\n    localparam [3:0] S_CALC = 4'd6;\n    localparam [3:0] S_UPDATE_BEST = 4'd7;\n    localparam [3:0] S_OUTPUT = 4'd8;\n    localparam [3:0] S_DONE = 4'd9;\n\n    reg [3:0] state;\n    reg [3:0] next_state;\n\n    // DP memory\n    reg [DATA_WIDTH-1:0] dp [0:MAX_TIME][0:STATE_SIZE-1];\n\n    // Precomputed powers\n    reg [DATA_WIDTH-1:0] f_power [0:MAX_TIME];\n\n    // Iteration variables\n    reg [3:0] t_idx;\n    reg [6:0] state_idx;\n    reg [1:0] bug_idx;\n\n    // Temporary registers\n    reg [DATA_WIDTH-1:0] p_current;\n    reg [DATA_WIDTH-1:0] one_minus_p;\n    reg [DATA_WIDTH-1:0] dp_success;\n    reg [DATA_WIDTH-1:0] dp_failure;\n    reg [DATA_WIDTH-1:0] term_success;\n    reg [DATA_WIDTH-1:0] term_failure;\n    reg [DATA_WIDTH-1:0] value;\n    reg [DATA_WIDTH-1:0] best;\n\n    // State decoding\n    wire [3:0] bug0_state = state_idx % (T+2);\n    wire [3:0] bug1_state = state_idx / (T+2);\n    wire bug0_fixed = (bug0_state == T+1);\n    wire bug1_fixed = (bug1_state == T+1);\n\n    wire [3:0] bug0_state_success = T+1;\n    wire [3:0] bug0_state_failure = (bug0_state < T) ? bug0_state + 1 : T;\n    wire [3:0] bug1_state_success = T+1;\n    wire [3:0] bug1_state_failure = (bug1_state < T) ? bug1_state + 1 : T;\n\n    wire [6:0] state_success_bug0 = bug0_state_success * (T+2) + bug1_state;\n    wire [6:0] state_failure_bug0 = bug0_state_failure * (T+2) + bug1_state;\n    wire [6:0] state_success_bug1 = bug0_state * (T+2) + bug1_state_success;\n    wire [6:0] state_failure_bug1 = bug0_state * (T+2) + bug1_state_failure;\n\n    // Fixed-point arithmetic functions\n    function [DATA_WIDTH-1:0] fp_mult;\n        input [DATA_WIDTH-1:0] a, b;\n        reg signed [127:0] prod;\n        begin\n            prod = a * b;\n            fp_mult = prod[95:32];\n        end\n    endfunction\n\n    function [DATA_WIDTH-1:0] fp_add;\n        input [DATA_WIDTH-1:0] a, b;\n        begin\n            fp_add = a + b;\n        end\n    endfunction\n\n    function [DATA_WIDTH-1:0] fp_sub;\n        input [DATA_WIDTH-1:0] a, b;\n        begin\n            fp_sub = a - b;\n        end\n    endfunction\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            expected_value <= 64'd0;\n            t_idx <= 4'd0;\n            state_idx <= 7'd0;\n            bug_idx <= 2'd0;\n            p_current <= 64'd0;\n            one_minus_p <= 64'd0;\n            dp_success <= 64'd0;\n            dp_failure <= 64'd0;\n            term_success <= 64'd0;\n            term_failure <= 64'd0;\n            value <= 64'd0;\n            best <= 64'd0;\n            for (integer i = 0; i < MAX_TIME; i = i + 1) begin\n                f_power[i] <= 64'd0;\n                for (integer j = 0; j < STATE_SIZE; j = j + 1) begin\n                    dp[i][j] <= 64'd0;\n                end\n            end\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    if (start) state <= S_PRECOMP;\n                    else state <= S_IDLE;\n                end\n\n                S_PRECOMP: begin\n                    // Compute f_power[k] for k=0..T\n                    f_power[0] <= 64'h0000000100000000;\n                    for (integer k = 1; k <= T; k = k + 1) begin\n                        f_power[k] <= fp_mult(f_power[k-1], f);\n                    end\n                    state <= S_INIT;\n                end\n\n                S_INIT: begin\n                    // Initialize dp[T][*] = 0\n                    for (integer i = 0; i < STATE_SIZE; i = i + 1) dp[T][i] <= 64'd0;\n                    t_idx <= T - 1;\n                    state_idx <= 7'd0;\n                    state <= S_LOOP_T;\n                end\n\n                S_LOOP_T: begin\n                    if (t_idx == 8'hFF) state <= S_OUTPUT;\n                    else state <= S_LOOP_STATE;\n                end\n\n                S_LOOP_STATE: begin\n                    if (state_idx >= STATE_SIZE) begin\n                        t_idx <= t_idx - 1;\n                        state_idx <= 7'd0;\n                        state <= S_LOOP_T;\n                    end else begin\n                        bug_idx <= 2'd0;\n                        best <= 64'd0;\n                        state <= S_LOOP_BUG;\n                    end\n                end\n\n                S_LOOP_BUG: begin\n                    if (bug_idx >= MAX_BUGS) begin\n                        dp[t_idx][state_idx] <= best;\n                        state_idx <= state_idx + 1;\n                        state <= S_LOOP_STATE;\n                    end else begin\n                        if ((bug_idx == 2'd0 && bug0_fixed) || (bug_idx == 2'd1 && bug1_fixed)) begin\n                            bug_idx <= bug_idx + 1;\n                        end else begin\n                            state <= S_CALC;\n                        end\n                    end\n                end\n\n                S_CALC: begin\n                    state <= S_UPDATE_BEST;\n                end\n\n                S_UPDATE_BEST: begin\n                    if (value > best) best <= value;\n                    bug_idx <= bug_idx + 1;\n                    state <= S_LOOP_BUG;\n                end\n\n                S_OUTPUT: begin\n                    expected_value <= dp[0][0];\n                    done <= 1'b1;\n                    state <= S_DONE;\n                end\n\n                S_DONE: begin\n                    done <= 1'b0;\n                    state <= S_IDLE;\n                end\n\n                default: state <= S_IDLE;\n            endcase\n        end\n    end\n\n    // Combinational logic for S_CALC\n    always @(*) begin\n        value = 64'd0;\n        p_current = 64'd0;\n        one_minus_p = 64'd0;\n        dp_success = 64'd0;\n        dp_failure = 64'd0;\n        term_success = 64'd0;\n        term_failure = 64'd0;\n\n        if (state == S_CALC) begin\n            if (bug_idx == 2'd0) begin\n                p_current = fp_mult(p[0], f_power[bug0_state]);\n                one_minus_p = fp_sub(64'h0000000100000000, p_current);\n                dp_success = dp[t_idx+1][state_success_bug0];\n                dp_failure = dp[t_idx+1][state_failure_bug0];\n            end else begin\n                p_current = fp_mult(p[1], f_power[bug1_state]);\n                one_minus_p = fp_sub(64'h0000000100000000, p_current);\n                dp_success = dp[t_idx+1][state_success_bug1];\n                dp_failure = dp[t_idx+1][state_failure_bug1];\n            end\n            term_success = fp_mult(p_current, fp_add(s[bug_idx], dp_success));\n            term_failure = fp_mult(one_minus_p, dp_failure);\n            value = fp_add(term_success, term_failure);\n        end\n    end\n\nendmodule